"use client";

import { useState } from "react";
import { createClient } from "@/lib/supabase/client";


export default function Availability(){


const supabase = createClient();


const [day,setDay] = useState("1");
const [start,setStart] = useState("09:00");
const [end,setEnd] = useState("17:00");

const [message,setMessage] = useState("");



async function save(){


const {
data:{user}
}=await supabase.auth.getUser();



const {data:groomer}=await supabase
.from("groomers")
.select("*")
.eq("user_id",user?.id)
.single();



const {error}=await supabase
.from("availability")
.insert({

groomer_id:groomer.id,

day_of_week:Number(day),

start_time:start,

end_time:end

});



if(error){

setMessage(error.message);

}else{

setMessage("✅ Hours saved!");

}


}




return (

<main className="min-h-screen bg-green-50 p-6">


<div className="max-w-md mx-auto bg-white rounded-3xl shadow p-8">


<h1 className="text-3xl font-bold">
🕒 Working Hours
</h1>



<select
className="border p-3 rounded-xl w-full mt-5"
value={day}
onChange={(e)=>setDay(e.target.value)}
>

<option value="0">Sunday</option>
<option value="1">Monday</option>
<option value="2">Tuesday</option>
<option value="3">Wednesday</option>
<option value="4">Thursday</option>
<option value="5">Friday</option>
<option value="6">Saturday</option>

</select>



<input
className="border p-3 rounded-xl w-full mt-4"
type="time"
value={start}
onChange={(e)=>setStart(e.target.value)}
/>



<input
className="border p-3 rounded-xl w-full mt-4"
type="time"
value={end}
onChange={(e)=>setEnd(e.target.value)}
/>




<button
onClick={save}
className="bg-green-600 text-white w-full py-3 rounded-xl mt-5"
>
Save Hours
</button>


<p className="mt-4">
{message}
</p>


</div>


</main>

)

}